var body = $input.first().json.body || $input.first().json;

var userId = body.user_id || 'f24ee278-fb1e-42dc-8777-ac9af1954d25';
var templateRef = body.template_ref || 'TEF-001';
var domainContext = body.domain_context || 'a UK regulatory form submission';
var apiKey = body.openai_api_key || '';
var supabaseUrl = body.supabase_url || 'https://egrzvwnjrtpwwmqzimff.supabase.co';

if (!apiKey) {
  throw new Error('Missing required field: openai_api_key. Pass it in the webhook POST body.');
}

var uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidPattern.test(userId)) {
  throw new Error('Invalid user_id format: "' + userId + '". Expected UUID.');
}

return [{
  json: {
    user_id: userId,
    template_ref: templateRef,
    domain_context: domainContext,
    OPENAI_API_KEY: apiKey,
    SUPABASE_URL: supabaseUrl
  }
}];

var config = $('Validate Params').first().json;
var userResult = $('Fetch User Details').first().json;
var tplResult = $input.first().json;

if (Array.isArray(userResult)) { userResult = userResult[0]; }
if (Array.isArray(tplResult)) { tplResult = tplResult[0]; }

if (!userResult || !userResult.details) {
  throw new Error('User details not found for user_id: ' + config.user_id);
}
if (!tplResult || !tplResult.source_to_template_mapping) {
  throw new Error('Template not found: ' + config.template_ref);
}

var details = userResult.details;
var mapping = tplResult.source_to_template_mapping;
var templateTitle = tplResult.title || config.template_ref;
var templateDesc = tplResult.description || '';

var mappingLookup = {};
for (var m = 0; m < mapping.length; m++) {
  var entry = mapping[m];
  if (entry.dataKey) {
    mappingLookup[entry.dataKey] = entry.pdfField || entry.dataKey;
  }
}

var syntheticFields = [];
var detailKeys = Object.keys(details);
for (var i = 0; i < detailKeys.length; i++) {
  var key = detailKeys[i];
  var val = String(details[key] || '');
  if (val.toLowerCase().indexOf('synthetic') === 0) {
    var pdfLabel = mappingLookup[key] || key;
    syntheticFields.push({
      dataKey: key,
      pdfFieldLabel: pdfLabel,
      currentValue: val
    });
  }
}

if (syntheticFields.length === 0) {
  throw new Error('No fields with "Synthetic" values found in user_details for user ' + config.user_id + '. Nothing to enrich. Run Generate Synthetic Data workflow first.');
}

var fieldList = '';
for (var f = 0; f < syntheticFields.length; f++) {
  var sf = syntheticFields[f];
  fieldList = fieldList + '- ' + sf.dataKey + ' (PDF label: "' + sf.pdfFieldLabel + '")\n';
}

var domainCtx = config.domain_context || 'a UK regulatory form submission';

var prompt = 'You are generating realistic test data for: ' + templateTitle + '.';
if (templateDesc) {
  prompt = prompt + ' Description: ' + templateDesc + '.';
}
prompt = prompt + '\n\nDomain context: ' + domainCtx + '.';
prompt = prompt + '\n\nFor each field below, provide a plausible, realistic value that would appear on a real application. Use UK formats where applicable (dates as DD/MM/YYYY, phone numbers as +44, postcodes, etc.). Values should be internally consistent (same company, same site address, etc.).';
prompt = prompt + '\n\nFields needing realistic values:\n' + fieldList;
prompt = prompt + '\nReturn ONLY a valid JSON object mapping each dataKey to its realistic value. No markdown, no explanation, just the JSON object. Example format:\n{\n  "field_key_1": "realistic value 1",\n  "field_key_2": "realistic value 2"\n}';

return [{
  json: {
    user_id: config.user_id,
    template_ref: config.template_ref,
    SUPABASE_URL: config.SUPABASE_URL,
    OPENAI_API_KEY: config.OPENAI_API_KEY,
    template_title: templateTitle,
    synthetic_field_count: syntheticFields.length,
    synthetic_fields: syntheticFields,
    existing_details: details,
    prompt: prompt
  }
}];

var config = $('Build LLM Prompt').first().json;
var apiResponse = $input.first().json;

// Parse LLM response
var responseText = '';
if (apiResponse.choices && apiResponse.choices.length > 0) {
  responseText = apiResponse.choices[0].message.content || '';
} else if (apiResponse.error) {
  throw new Error('OpenAI API error: ' + JSON.stringify(apiResponse.error));
} else {
  throw new Error('Unexpected OpenAI API response: ' + JSON.stringify(apiResponse));
}

responseText = responseText.trim();
if (responseText.indexOf('```') >= 0) {
  var startIdx = responseText.indexOf('{');
  var endIdx = responseText.lastIndexOf('}');
  if (startIdx >= 0 && endIdx > startIdx) {
    responseText = responseText.substring(startIdx, endIdx + 1);
  }
}

var realisticValues = {};
try {
  realisticValues = JSON.parse(responseText);
} catch (e) {
  throw new Error('Failed to parse LLM response as JSON. Raw response: ' + responseText.substring(0, 500));
}

var keys = Object.keys(realisticValues);
if (keys.length === 0) {
  throw new Error('LLM returned empty JSON object. Raw response: ' + responseText.substring(0, 500));
}

// Merge realistic values into existing details
var existingDetails = config.existing_details || {};
var mergedDetails = JSON.parse(JSON.stringify(existingDetails));
var replaced = [];
for (var i = 0; i < keys.length; i++) {
  var dk = keys[i];
  var oldVal = mergedDetails[dk] || '(missing)';
  mergedDetails[dk] = realisticValues[dk];
  replaced.push(dk + ': ' + String(realisticValues[dk]).substring(0, 60));
}

return [{
  json: {
    user_id: config.user_id,
    template_ref: config.template_ref,
    template_title: config.template_title,
    SUPABASE_URL: config.SUPABASE_URL,
    field_count: keys.length,
    realistic_values: realisticValues,
    merged_details: mergedDetails,
    replaced_summary: replaced
  }
}];

var parsed = $('Parse LLM Response').first().json;
var updateResult = $input.first().json;

// Check if the PATCH returned updated rows
var updated = Array.isArray(updateResult) ? updateResult : [updateResult];
var success = updated.length > 0 && updated[0].id;

var result = {
  status: success ? 'applied' : 'error',
  message: success
    ? 'Realistic data generated and applied for ' + parsed.field_count + ' fields.'
    : 'Failed to update user_details. Check Supabase response.',
  template_ref: parsed.template_ref,
  template_title: parsed.template_title,
  user_id: parsed.user_id,
  fields_updated: parsed.field_count,
  replaced_summary: parsed.replaced_summary,
  realistic_values: parsed.realistic_values
};

if (!success) {
  result.supabase_response = updateResult;
}

return [{ json: result }];
